import re, serial, time
p='/dev/cu.usbserial-1130'
h=serial.Serial(p,115200,timeout=0.1,write_timeout=1)
h.dtr=False; h.rts=False
time.sleep(1.0)
h.reset_input_buffer()

def snapshot():
    h.write(b'status\n'); h.flush()
    buf=bytearray(); end=time.monotonic()+8.0
    while time.monotonic()<end:
        n=h.in_waiting
        if n:
            buf.extend(h.read(n))
            if b'growbox> ' in buf:
                break
        time.sleep(0.02)
    text=buf.decode(errors='replace')
    lines=[x.strip() for x in text.replace('\r','').split('\n') if x.strip()]
    status=[x for x in lines if x.startswith('status ')]
    timing=[x for x in lines if x.startswith('timing ')]
    tasks=[x for x in lines if x.startswith('task ') and ' severity=' in x]
    if len(status)!=1 or len(timing)!=1:
        raise SystemExit('incomplete status response: '+repr(text[-2000:]))
    if not tasks:
        raise SystemExit('no complete task lines')
    return status[0], timing[0], tasks, text

shots=[]
for i in range(3):
    shots.append(snapshot()); time.sleep(0.5)
h.close()

def field(line,key):
    m=re.search(r'(?:^| )'+re.escape(key)+r'=([^ ]+)', line)
    if not m: raise SystemExit('missing '+key+' in '+line)
    return m.group(1)

boot_ids=[]
for idx,(status,timing,tasks,text) in enumerate(shots,1):
    if field(status,'firmware_sha')!='3058625be2f35c121afcf82549d5c73068839ecd': raise SystemExit('wrong firmware')
    if field(status,'outputs')!='fake-locked': raise SystemExit('outputs not fake-locked')
    boot_ids.append(field(status,'boot_id'))
    critical=[x for x in tasks if 'severity=critical' in x]
    if critical: raise SystemExit('critical task stack: '+repr(critical))
    store=[x for x in tasks if 'name=stage27_store ' in x]
    if len(store)!=1: raise SystemExit('missing complete stage27_store line')
    hwm=int(field(store[0],'hwm_bytes')); configured=int(field(store[0],'configured_stack_bytes'))
    if hwm*100 < configured*25: raise SystemExit('stage27_store margin below 25 percent: '+store[0])
    if int(field(timing,'loop_overruns')) != 0: raise SystemExit('loop overrun observed')
    print(f'SNAPSHOT_{idx}_STATUS', status)
    print(f'SNAPSHOT_{idx}_TIMING', timing)
    print(f'SNAPSHOT_{idx}_STAGE27_STORE', store[0])
if len(set(boot_ids))!=1: raise SystemExit('boot id changed across snapshots: '+repr(boot_ids))
print('STAGE28E_A_HW_BOOT_ID_STABLE', boot_ids[0])
print('STAGE28E_A_HW_CONFIRM_PASS')
